reference.setup:
{
    ref_curve <- function(x, p) p[1] + (p[2] - p[1])/(1 + 10^((p[3] - x) * p[4]))
    ref_jacobian <- function(x, p) {
        sapply(1:4, function(j) {
            h <- 1e-04
            at <- function(k) {
                q <- p
                q[j] <- p[j] + k * h
                ref_curve(x, q)
            }
            (at(-2) - 8 * at(-1) + 8 * at(1) - at(2))/(12 * h)
        })
    }
    ref_runs <- function(s) {
        n1 <- sum(s > 0)
        n2 <- sum(s < 0)
        r <- 1 + sum(s[-1] != s[-length(s)])
        m <- 2 * n1 * n2/(n1 + n2) + 1
        v <- (m - 1) * (m - 2)/(n1 + n2 - 1)
        z <- (r - m)/sqrt(v)
        list(ran = TRUE, n_runs = r, n_pos = n1, n_neg = n2, z = z, p = 2 * pnorm(-abs(z)))
    }
    ref_optimum <- function(x, y, start = NULL) {
        best <- c(Inf, NA, NA, NA, NA)
        if (!is.null(start)) 
            best <- c(0, start)
        if (is.null(start)) 
            for (l in seq(min(x), max(x), length.out = 41)) {
                for (h in c(-seq(0.1, 5, by = 0.05), seq(0.1, 5, by = 0.05))) {
                  f <- 1/(1 + 10^((l - x) * h))
                  X <- cbind(1 - f, f)
                  co <- qr.coef(qr(X), y)
                  if (any(!is.finite(co))) 
                    next
                  rss <- sum((y - X %*% co)^2)
                  if (rss < best[1]) 
                    best <- c(rss, co, l, h)
                }
            }
        p <- unname(best[2:5])
        rss <- function(p) sum((y - ref_curve(x, p))^2)
        lambda <- 0.001
        for (it in 1:1000) {
            J <- ref_jacobian(x, p)
            A <- crossprod(J)
            step <- unname(drop(solve(A + lambda * diag(diag(A)), crossprod(J, y - 
                ref_curve(x, p)))))
            if (rss(p + step) <= rss(p)) {
                p <- p + step
                lambda <- lambda/10
            }
            else {
                lambda <- lambda * 10
            }
            if (max(abs(step)/pmax(abs(p), 1e-08)) < 1e-14 || lambda > 1e+12) 
                break
        }
        for (it in 1:5) {
            J <- ref_jacobian(x, p)
            p <- p + unname(drop(qr.coef(qr(J), y - ref_curve(x, p))))
        }
        if (p[1] > p[2]) 
            p <- c(p[2], p[1], p[3], -p[4])
        p
    }
    ref_param <- function(value, se, t, dependency) {
        list(value = value, se = se, lower = value - t * se, upper = value + t * 
            se, dependency = dependency, ambiguous = dependency > 0.9999)
    }
    run_fpl <- function(dose, y, log_x = TRUE) {
        dropped <- if (log_x) 
            0
        else sum(dose <= 0)
        if (!log_x) {
            y <- y[dose > 0]
            dose <- dose[dose > 0]
        }
        x <- if (log_x) 
            dose
        else log10(dose)
        back <- if (log_x) 
            function(v) v
        else function(v) 10^v
        n <- length(x)
        p <- ref_optimum(x, y)
        J <- ref_jacobian(x, p)
        A <- crossprod(J)
        Ainv <- solve(A)
        fitted <- ref_curve(x, p)
        resid <- y - fitted
        df <- n - 4
        ss <- sum(resid^2)
        s2 <- ss/df
        se <- sqrt(s2 * diag(Ainv))
        dependency <- 1 - 1/(diag(A) * diag(Ainv))
        t <- qt(0.975, df)
        ord <- order(x)
        signs <- sign(resid[ord])
        grid <- seq(min(x), max(x), length.out = 100)
        G <- ref_jacobian(grid, p)
        var_fit <- vapply(seq_along(grid), function(i) drop(G[i, ] %*% Ainv %*% G[i, 
            ]), 0) * s2
        fit_grid <- ref_curve(grid, p)
        list(n = n, dropped = dropped, ran = TRUE, bottom = ref_param(p[1], se[1], 
            t, dependency[1]), top = ref_param(p[2], se[2], t, dependency[2]), logec50 = ref_param(p[3], 
            se[3], t, dependency[3]), hill = ref_param(p[4], se[4], t, dependency[4]), 
            ec50 = 10^p[3], ec50_lower = 10^(p[3] - t * se[3]), ec50_upper = 10^(p[3] + 
                t * se[3]), df = df, ss = ss, syx = sqrt(s2), r2 = 1 - ss/sum((y - 
                mean(y))^2), x = back(x[ord]), y = y[ord], fitted = fitted[ord], 
            residual = resid[ord], runs = ref_runs(signs[signs != 0]), band = list(x = back(grid), 
                fit = fit_grid, confidence_lower = fit_grid - t * sqrt(var_fit), 
                confidence_upper = fit_grid + t * sqrt(var_fit), prediction_lower = fit_grid - 
                  t * sqrt(var_fit + s2), prediction_upper = fit_grid + t * sqrt(var_fit + 
                  s2)))
    }
}

